package dev.martianzoo.tfm.web.almanac

import dev.martianzoo.pets.types.Class

/** A class detail view or the complete results of a relation shown in that view. */
internal sealed interface AlmanacColumn {
  val klass: Class

  data class Details(override val klass: Class) : AlmanacColumn

  data class Results(override val klass: Class, val group: String) : AlmanacColumn
}
